def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def cma_es(pop_size=10, sigma0=1.0, step_size=0.5, restart_budget=100):
        mean = rng.uniform(lb, ub, size=dim)
        cov = np.eye(dim) * 0.01
        sigma = sigma0

        for _ in range(budget):
            pop = rng.multivariate_normal(mean, cov, pop_size)
            pop = clip(pop)

            fitness = [func(x) for x in pop]

            new_mean = (1 - step_size) * mean + step_size / pop_size * np.dot(np.array(fitness).T, pop)
            new_cov = (1 - step_size) * cov + step_size / (pop_size - 1) * np.outer(pop[0] - new_mean, pop[0] - new_mean)

            sigma_new = np.sqrt((np.linalg.det(new_cov)) ** (1/dim))
            if sigma_new < 10e-6 or _ > restart_budget:
                mean = rng.uniform(lb, ub, size=dim)
                cov = np.eye(dim) * 0.01
                sigma = sigma0

            sigma = min(sigma + step_size / pop_size * (sigma_new - sigma), 100)

            mean = clip(new_mean)
            cov = clip(new_cov)

        return mean

    return cma_es()

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    def cma_es(func, x0, dim, pop_size=50, max_iter=100, sigma=1.0):
        best_x = x0
        best_f = func(best_x)
        for i in range(max_iter):
            X = rng.normal(size=(pop_size, dim)) + x0
            f_X = func(clip(X, lb, ub))
            if np.all(f_X == 0):
                return clip(X[np.argmin(f_X)], lb, ub)
            best_i = np.argmin(f_X)
            if f_X[best_i] < best_f:
                best_x = X[best_i]
                best_f = f_X[best_i]
        return best_x

    def gradient_descent(func, x0, dim, max_iter=100, alpha=1e-4):
        best_x = x0
        for i in range(max_iter):
            g_x = np.array([2 * 200 * (x[i] - x[i-1]**2) * (x[i+1] - x[i-1]**2) + 2 * (x[i] - 1)
                            if i > 0 and i < dim else
                            2 * (x[i] - 1)
                            for i in range(dim)])
            x_new = clip(x0 - alpha * g_x, lb, ub)
            if func(x_new) < func(best_x):
                best_x = x_new
        return best_x

    x = cma_es(func, rng.uniform(size=dim), dim, pop_size=int(budget/10))
